{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2178-10-18 16:00:00",
      "speaker": "Doctor",
      "text": "Hello Mr. ___, I'm Dr. ___. I'll be helping manage your care during this hospital stay. I understand you've been feeling more swollen lately?"
    },
    {
      "turn_number": 2,
      "time": "2178-10-18 16:02:00",
      "speaker": "Patient",
      "text": "Yes, doctor. My belly’s been getting bigger and my legs are swollen up to my thighs. I can barely walk a block now without getting winded."
    },
    {
      "turn_number": 3,
      "time": "2178-10-18 16:04:00",
      "speaker": "Doctor",
      "text": "I see. Given your history of cirrhosis and portopulmonary hypertension, this sounds like fluid buildup. We’re going to start some IV diuretics to help remove the excess fluid."
    },
    {
      "turn_number": 4,
      "time": "2178-10-18 16:06:00",
      "speaker": "Patient",
      "text": "Okay. I’ve been on diuretics at home—spironolactone and torsemide—but they haven’t been helping much."
    },
    {
      "turn_number": 5,
      "time": "2178-10-18 16:08:00",
      "speaker": "Doctor",
      "text": "Yes, your liver team mentioned you’ve increased them recently. Sometimes oral meds aren’t enough when fluid overload gets worse. We’ll use IV Lasix to boost the effect."
    },
    {
      "turn_number": 6,
      "time": "2178-10-18 16:10:00",
      "speaker": "Patient",
      "text": "Makes sense. I’ve also been getting weekly paracenteses. Last one took out about 9 liters."
    },
    {
      "turn_number": 7,
      "time": "2178-10-18 16:12:00",
      "speaker": "Doctor",
      "text": "That’s a lot. We plan to do another therapeutic paracentesis soon, after some lab work. We also need to do a right heart catheterization to check your pressures for transplant listing."
    },
    {
      "turn_number": 8,
      "time": "2178-10-18 16:14:00",
      "speaker": "Patient",
      "text": "Right, the exception MELD score. I remember from last time. Will that be safe with my low platelets?"
    },
    {
      "turn_number": 9,
      "time": "2178-10-18 16:16:00",
      "speaker": "Doctor",
      "text": "Good question. Your platelets are low at 32,000, but we’ll monitor closely. The procedure is low risk, and we’ll take precautions."
    },
    {
      "turn_number": 10,
      "time": "2178-10-18 16:18:00",
      "speaker": "Patient",
      "text": "Okay, I trust you. I just want to get back on track for transplant."
    },
    {
      "turn_number": 11,
      "time": "2178-10-18 16:20:00",
      "speaker": "Doctor",
      "text": "We’ll make sure everything is optimized. Your treprostinil infusion is running smoothly, and we’ll keep all your other meds going."
    },
    {
      "turn_number": 12,
      "time": "2178-10-18 19:05:00",
      "speaker": "Doctor",
      "text": "We just got your chest X-ray back. The central line we placed is in a good position, and your lung bases are clearer than before."
    },
    {
      "turn_number": 13,
      "time": "2178-10-18 19:07:00",
      "speaker": "Patient",
      "text": "That’s good. I haven’t had any chest pain or fever, so I hoped things were okay."
    },
    {
      "turn_number": 14,
      "time": "2178-10-18 19:09:00",
      "speaker": "Doctor",
      "text": "No signs of infection or pneumothorax. Your abdominal X-ray also confirms the Dobbhoff tube is in place, so your tube feeding can continue."
    },
    {
      "turn_number": 15,
      "time": "2178-10-18 19:11:00",
      "speaker": "Patient",
      "text": "I’ve been on Isocal through the tube. It helps with my nutrition, but I still feel weak."
    },
    {
      "turn_number": 16,
      "time": "2178-10-18 19:13:00",
      "speaker": "Doctor",
      "text": "We know you're malnourished, so we’re continuing the tube feeds, megestrol, and multivitamins to support you."
    },
    {
      "turn_number": 17,
      "time": "2178-10-19 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs show your kidney function is stable, and your liver enzymes are similar to baseline. We’ll keep pushing fluids out."
    },
    {
      "turn_number": 18,
      "time": "2178-10-19 08:02:00",
      "speaker": "Patient",
      "text": "Any change in my weight yet?"
    },
    {
      "turn_number": 19,
      "time": "2178-10-19 08:04:00",
      "speaker": "Doctor",
      "text": "You were 101 kg on admission. Today you’re down to 98 kg. We’re making progress, but there’s more to go. Your dry weight is estimated at 86 kg."
    },
    {
      "turn_number": 20,
      "time": "2178-10-19 08:06:00",
      "speaker": "Patient",
      "text": "That’s going to take a while. I hope I can breathe easier once the fluid’s gone."
    },
    {
      "turn_number": 21,
      "time": "2178-10-19 08:08:00",
      "speaker": "Doctor",
      "text": "That’s the goal. We’ll keep adjusting your IV diuretics and monitor your electrolytes closely."
    },
    {
      "turn_number": 22,
      "time": "2178-10-20 09:00:00",
      "speaker": "Doctor",
      "text": "We’re scheduled to do your paracentesis today. We’ll remove as much fluid as we safely can."
    },
    {
      "turn_number": 23,
      "time": "2178-10-20 09:02:00",
      "speaker": "Patient",
      "text": "Will it hurt?"
    },
    {
      "turn_number": 24,
      "time": "2178-10-20 09:04:00",
      "speaker": "Doctor",
      "text": "We’ll use local anesthesia. You might feel pressure, but not sharp pain. It usually helps breathing and comfort right away."
    },
    {
      "turn_number": 25,
      "time": "2178-10-20 10:30:00",
      "speaker": "Doctor",
      "text": "The procedure went well. We removed 7.6 liters of fluid. You tolerated it without any issues."
    },
    {
      "turn_number": 26,
      "time": "2178-10-20 10:32:00",
      "speaker": "Patient",
      "text": "Wow, that’s a lot. I already feel a little lighter."
    },
    {
      "turn_number": 27,
      "time": "2178-10-20 10:34:00",
      "speaker": "Doctor",
      "text": "That’s great. Your weight is now 95 kg. We’ll keep the diuresis going and prepare for your heart cath later this week."
    },
    {
      "turn_number": 28,
      "time": "2178-10-21 08:00:00",
      "speaker": "Doctor",
      "text": "Your labs this morning show your potassium is a bit low. We’re giving some replacement and will keep monitoring."
    },
    {
      "turn_number": 29,
      "time": "2178-10-21 08:02:00",
      "speaker": "Patient",
      "text": "I’ve been on potassium before. Is this from the diuretics?"
    },
    {
      "turn_number": 30,
      "time": "2178-10-21 08:04:00",
      "speaker": "Doctor",
      "text": "Exactly. Lasix can lower potassium, so we check it daily. We’ll adjust as needed to keep you safe."
    },
    {
      "turn_number": 31,
      "time": "2178-10-22 09:00:00",
      "speaker": "Doctor",
      "text": "We noticed your left leg is more swollen than the right. We did an ultrasound to check for a blood clot."
    },
    {
      "turn_number": 32,
      "time": "2178-10-22 09:02:00",
      "speaker": "Patient",
      "text": "Oh, I was worried about that. Is there a clot?"
    },
    {
      "turn_number": 33,
      "time": "2178-10-22 09:04:00",
      "speaker": "Doctor",
      "text": "No, the ultrasound showed no DVT. The swelling is likely from the fluid overload, which should improve."
    },
    {
      "turn_number": 34,
      "time": "2178-10-22 09:06:00",
      "speaker": "Patient",
      "text": "That’s a relief. I’ve had infections before, so I get nervous."
    },
    {
      "turn_number": 35,
      "time": "2178-10-22 09:08:00",
      "speaker": "Doctor",
      "text": "Understandable. We’re continuing your ciprofloxacin to prevent infections, especially with low platelets."
    },
    {
      "turn_number": 36,
      "time": "2178-10-23 08:00:00",
      "speaker": "Doctor",
      "text": "You’re down to 94 kg. Your breathing has improved, and your edema is decreasing."
    },
    {
      "turn_number": 37,
      "time": "2178-10-23 08:02:00",
      "speaker": "Patient",
      "text": "I can walk to the end of the hall now without stopping. That’s progress."
    },
    {
      "turn_number": 38,
      "time": "2178-10-23 08:04:00",
      "speaker": "Doctor",
      "text": "Excellent. We’ll keep your IV diuretics going at a lower dose and prepare for your right heart cath tomorrow."
    },
    {
      "turn_number": 39,
      "time": "2178-10-24 08:00:00",
      "speaker": "Doctor",
      "text": "Just a heads-up—your heart cath is scheduled for tomorrow. It’s to measure pressures in your lungs for your transplant evaluation."
    },
    {
      "turn_number": 40,
      "time": "2178-10-24 08:02:00",
      "speaker": "Patient",
      "text": "I remember. They’ll go through the groin, right?"
    },
    {
      "turn_number": 41,
      "time": "2178-10-24 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, through the femoral vein. It’s done with local anesthesia, and you’ll be awake but relaxed."
    },
    {
      "turn_number": 42,
      "time": "2178-10-24 08:06:00",
      "speaker": "Patient",
      "text": "Okay. Any risks I should know about?"
    },
    {
      "turn_number": 43,
      "time": "2178-10-24 08:08:00",
      "speaker": "Doctor",
      "text": "Bleeding is a small risk, especially with low platelets, but we’ll monitor closely. The benefits for your transplant listing outweigh the risks."
    },
    {
      "turn_number": 44,
      "time": "2178-10-25 13:00:00",
      "speaker": "Doctor",
      "text": "The right heart cath is complete. It went well. Your mean pulmonary artery pressure is 24 mmHg."
    },
    {
      "turn_number": 45,
      "time": "2178-10-25 13:02:00",
      "speaker": "Patient",
      "text": "Is that good?"
    },
    {
      "turn_number": 46,
      "time": "2178-10-25 13:04:00",
      "speaker": "Doctor",
      "text": "Yes, it’s an improvement from before. It shows your pulmonary hypertension is responding to treatment."
    },
    {
      "turn_number": 47,
      "time": "2178-10-25 13:06:00",
      "speaker": "Patient",
      "text": "That’s great news. Does that help with transplant?"
    },
    {
      "turn_number": 48,
      "time": "2178-10-25 13:08:00",
      "speaker": "Doctor",
      "text": "It does. This data supports your exception MELD request. The transplant team will review it."
    },
    {
      "turn_number": 49,
      "time": "2178-10-26 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs are stable. We’re planning to discharge you today."
    },
    {
      "turn_number": 50,
      "time": "2178-10-26 07:02:00",
      "speaker": "Patient",
      "text": "That’s great. What changes to my meds?"
    },
    {
      "turn_number": 51,
      "time": "2178-10-26 07:04:00",
      "speaker": "Doctor",
      "text": "We’re increasing your torsemide to 60 mg daily. It’s important to stay on top of fluid retention."
    },
    {
      "turn_number": 52,
      "time": "2178-10-26 07:06:00",
      "speaker": "Patient",
      "text": "I’ll take it as prescribed. Any other instructions?"
    },
    {
      "turn_number": 53,
      "time": "2178-10-26 07:08:00",
      "speaker": "Doctor",
      "text": "Weigh yourself every morning. Call if you gain more than 3 pounds in a day. You’ll need weekly paracenteses at the clinic."
    },
    {
      "turn_number": 54,
      "time": "2178-10-26 07:10:00",
      "speaker": "Patient",
      "text": "I already have that scheduled. What about labs?"
    },
    {
      "turn_number": 55,
      "time": "2178-10-26 07:12:00",
      "speaker": "Doctor",
      "text": "Yes, get your potassium and kidney function checked in a few days. Your sister has the lab order."
    },
    {
      "turn_number": 56,
      "time": "2178-10-26 07:14:00",
      "speaker": "Patient",
      "text": "She’ll take me. I’m glad I’m going home."
    },
    {
      "turn_number": 57,
      "time": "2178-10-26 07:16:00",
      "speaker": "Doctor",
      "text": "You did well. Keep taking all your other meds—spironolactone, rifaximin, omeprazole, and your pain and depression treatments."
    },
    {
      "turn_number": 58,
      "time": "2178-10-26 07:18:00",
      "speaker": "Patient",
      "text": "I will. And the testosterone patch and calcium too?"
    },
    {
      "turn_number": 59,
      "time": "2178-10-26 07:20:00",
      "speaker": "Doctor",
      "text": "Yes, continue those. They’re important for your strength and bone health."
    },
    {
      "turn_number": 60,
      "time": "2178-10-26 07:22:00",
      "speaker": "Patient",
      "text": "Thank you, doctor. I feel better already."
    },
    {
      "turn_number": 61,
      "time": "2178-10-26 07:24:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll see you in follow-up. Take care and call if anything changes."
    },
    {
      "turn_number": 62,
      "time": "2178-10-26 07:26:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 63,
      "time": "2178-10-26 07:28:00",
      "speaker": "Doctor",
      "text": "The nursing team will get your discharge papers ready. You should be out by noon."
    },
    {
      "turn_number": 64,
      "time": "2178-10-26 07:30:00",
      "speaker": "Patient",
      "text": "Perfect. I’m ready to go home."
    },
    {
      "turn_number": 65,
      "time": "2178-10-26 07:32:00",
      "speaker": "Doctor",
      "text": "You’ve made great progress. Keep up the good work with your care team."
    },
    {
      "turn_number": 66,
      "time": "2178-10-26 07:34:00",
      "speaker": "Patient",
      "text": "I will. I want to stay strong for transplant."
    },
    {
      "turn_number": 67,
      "time": "2178-10-26 07:36:00",
      "speaker": "Doctor",
      "text": "That’s the spirit. We’re all rooting for you."
    },
    {
      "turn_number": 68,
      "time": "2178-10-26 07:38:00",
      "speaker": "Patient",
      "text": "Appreciate it."
    },
    {
      "turn_number": 69,
      "time": "2178-10-26 07:40:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. ___. We’ll be in touch with your outpatient team."
    },
    {
      "turn_number": 70,
      "time": "2178-10-26 07:42:00",
      "speaker": "Patient",
      "text": "Thank you, doctor."
    },
    {
      "turn_number": 71,
      "time": "2178-10-26 07:44:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Have a safe trip home."
    },
    {
      "turn_number": 72,
      "time": "2178-10-26 07:46:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 73,
      "time": "2178-10-26 07:48:00",
      "speaker": "Doctor",
      "text": "Call if you have any trouble breathing or swelling comes back quickly."
    },
    {
      "turn_number": 74,
      "time": "2178-10-26 07:50:00",
      "speaker": "Patient",
      "text": "I will. I know the signs now."
    },
    {
      "turn_number": 75,
      "time": "2178-10-26 07:52:00",
      "speaker": "Doctor",
      "text": "Good. Stay consistent with your weight checks and meds."
    },
    {
      "turn_number": 76,
      "time": "2178-10-26 07:54:00",
      "speaker": "Patient",
      "text": "I will. Thanks for everything."
    },
    {
      "turn_number": 77,
      "time": "2178-10-26 07:56:00",
      "speaker": "Doctor",
      "text": "You’re doing great. Keep it up."
    },
    {
      "turn_number": 78,
      "time": "2178-10-26 07:58:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 79,
      "time": "2178-10-26 08:00:00",
      "speaker": "Doctor",
      "text": "We’ll be in touch with your sister and brother as contacts."
    },
    {
      "turn_number": 80,
      "time": "2178-10-26 08:02:00",
      "speaker": "Patient",
      "text": "They’ll help me stay on track."
    },
    {
      "turn_number": 81,
      "time": "2178-10-26 08:04:00",
      "speaker": "Doctor",
      "text": "That’s good support. Let them know if you need anything."
    },
    {
      "turn_number": 82,
      "time": "2178-10-26 08:06:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 83,
      "time": "2178-10-26 08:08:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. ___. We’ll see you soon."
    },
    {
      "turn_number": 84,
      "time": "2178-10-26 08:10:00",
      "speaker": "Patient",
      "text": "Bye, doctor."
    },
    {
      "turn_number": 85,
      "time": "2178-10-26 08:12:00",
      "speaker": "Doctor",
      "text": "Goodbye."
    }
  ],
  "summary": {
    "admission_start": "2178-10-18 15:56:00",
    "admission_end": "2178-10-26 13:52:00",
    "summary_paragraph": "Mr. ___ was admitted for volume overload due to decompensated cirrhosis and portopulmonary hypertension. He presented with worsening ascites and bilateral lower extremity edema refractory to oral diuretics. During the 8-day admission, he received aggressive IV diuresis and underwent a therapeutic paracentesis, removing 7.6 liters of fluid. His weight decreased from 101 kg to 93.9 kg. A right heart catheterization was performed, showing a mean pulmonary artery pressure of 24 mmHg, indicating improved pulmonary hemodynamics. He remained on chronic medications including treprostinil, spironolactone, and rifaximin. He was discharged home with an increased dose of torsemide, instructions to monitor daily weight, and plans for weekly paracenteses and outpatient follow-up.",
    "problems": [
      "Chronic hepatitis C with hepatic coma",
      "Portal hypertension",
      "Other ascites",
      "Esophageal varices in diseases classified elsewhere, without mention of bleeding",
      "Other pancytopenia",
      "Unspecified protein-calorie malnutrition",
      "Cirrhosis of liver without mention of alcohol",
      "Awaiting organ transplant status",
      "Osteoporosis, unspecified",
      "Edema",
      "Other testicular hypofunction",
      "Depressive disorder, not elsewhere classified",
      "Esophageal reflux"
    ]
  }
}
